-- Best Nails loyalty: the whole schema as of 26 Oct 2026, merged from the development
-- migrations into one starting point (generated by `supabase migration squash`, then the
-- settings row below added by hand, since a squash keeps the schema but not data).
--
-- Every point and gift voucher change goes through the security-definer functions here;
-- CLAUDE.md describes how they fit together. Change the schema with new migrations after this
-- one; never edit it once it has been applied anywhere.



SET statement_timeout = 0;
SET lock_timeout = 0;
SET idle_in_transaction_session_timeout = 0;
SET client_encoding = 'UTF8';
SET standard_conforming_strings = on;
SELECT pg_catalog.set_config('search_path', '', false);
SET check_function_bodies = false;
SET xmloption = content;
SET client_min_messages = warning;
SET row_security = off;

-- Functions are locked down by default: nobody can call one until a GRANT below allows it
-- (authenticated for admin functions, service_role for kiosk ones). A squash dump leaves this
-- out, because Supabase sets its own default grants, so it's restated here before any
-- function is created.
alter default privileges in schema public revoke execute on functions from public, anon, authenticated;


COMMENT ON SCHEMA "public" IS 'standard public schema';



CREATE EXTENSION IF NOT EXISTS "pg_stat_statements" WITH SCHEMA "extensions";






CREATE EXTENSION IF NOT EXISTS "pgcrypto" WITH SCHEMA "extensions";






CREATE EXTENSION IF NOT EXISTS "supabase_vault" WITH SCHEMA "vault";






CREATE EXTENSION IF NOT EXISTS "uuid-ossp" WITH SCHEMA "extensions";






CREATE TYPE "public"."check_in_source" AS ENUM (
    'kiosk',
    'admin'
);


ALTER TYPE "public"."check_in_source" OWNER TO "postgres";


CREATE TYPE "public"."gift_voucher_entry" AS ENUM (
    'sale',
    'spend',
