CREATE OR REPLACE FUNCTION "public"."_discount_used_today"("p_customer_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with day as (
    select (date_trunc('day', now() at time zone s.timezone) at time zone s.timezone) as start from public.settings s where s.id
  )
  select exists (
    select 1 from public.point_transactions t, day
     where t.customer_id = p_customer_id and t.reason = 'redeem' and t.created_at >= day.start
  ) or exists (
    select 1 from public.birthday_redemptions b, day
     where b.customer_id = p_customer_id and b.created_at >= day.start
  );
$$;


ALTER FUNCTION "public"."_discount_used_today"("p_customer_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_luhn_check_digit"("p_digits" "text") RETURNS integer
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
declare
  v_sum integer := 0;
  v_digit integer;
  v_double boolean := true;
begin
  -- From the right, every other digit is doubled (the check digit itself goes on the end).
  for i in reverse length(p_digits)..1 loop
    v_digit := substr(p_digits, i, 1)::integer;
    if v_double then
      v_digit := v_digit * 2;
      if v_digit > 9 then
        v_digit := v_digit - 9;
      end if;
    end if;
    v_sum := v_sum + v_digit;
    v_double := not v_double;
  end loop;
  return (10 - v_sum % 10) % 10;
end;
$$;


ALTER FUNCTION "public"."_luhn_check_digit"("p_digits" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_new_gift_voucher_code"() RETURNS "text"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  v_prefix text := (select code_prefix from public.settings where id);
  v_bytes bytea;
  v_byte integer;
  v_digits text;
  v_code text;
begin
  loop
    v_digits := '';
    while length(v_digits) < 7 loop
      v_bytes := extensions.gen_random_bytes(16);
      for i in 0..15 loop
        v_byte := get_byte(v_bytes, i);
        -- Bytes 250–255 are skipped, so every digit is equally likely.
        if v_byte < 250 and length(v_digits) < 7 then
          v_digits := v_digits || (v_byte % 10)::text;
        end if;
      end loop;
    end loop;
    v_code := v_prefix || v_digits || public._luhn_check_digit(v_digits)::text;
    exit when not exists (select 1 from public.gift_vouchers where code = v_code);
  end loop;
  return v_code;
end;
$$;


ALTER FUNCTION "public"."_new_gift_voucher_code"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_post_gift_voucher"("p_gift_voucher_id" "uuid", "p_kind" "public"."gift_voucher_entry", "p_delta_cents" integer, "p_customer_id" "uuid" DEFAULT NULL::"uuid", "p_note" "text" DEFAULT NULL::"text", "p_undoes" "uuid" DEFAULT NULL::"uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_balance integer;
begin
  perform set_config('best_nails.ledger_write', 'on', true);
  update public.gift_vouchers
     set balance_cents = balance_cents + p_delta_cents
   where id = p_gift_voucher_id
  returning balance_cents into v_balance;
  insert into public.gift_voucher_transactions
    (gift_voucher_id, kind, delta_cents, balance_after_cents, customer_id, note, undoes, created_by)
  values (p_gift_voucher_id, p_kind, p_delta_cents, v_balance, p_customer_id, nullif(trim(p_note), ''), p_undoes, (select auth.uid()));
  perform set_config('best_nails.ledger_write', 'off', true);
  return v_balance;
end;
$$;


ALTER FUNCTION "public"."_post_gift_voucher"("p_gift_voucher_id" "uuid", "p_kind" "public"."gift_voucher_entry", "p_delta_cents" integer, "p_customer_id" "uuid", "p_note" "text", "p_undoes" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_post_points"("p_customer_id" "uuid", "p_delta" integer, "p_reason" "public"."point_reason", "p_check_in_id" "uuid" DEFAULT NULL::"uuid", "p_promotion_id" "uuid" DEFAULT NULL::"uuid", "p_note" "text" DEFAULT NULL::"text", "p_actor" "uuid" DEFAULT NULL::"uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_balance integer;
begin
  perform set_config('best_nails.ledger_write', 'on', true);

  update public.customers
     set points_balance = points_balance + p_delta,
         -- Lifetime counts points earned; redeeming doesn't lower it, undoing a visit does.
         lifetime_points = greatest(lifetime_points + case
                             when p_reason = 'void' then p_delta
                             when p_delta > 0 then p_delta
                             else 0
                           end, 0)
   where id = p_customer_id
  returning points_balance into v_balance;

  insert into public.point_transactions (customer_id, delta, balance_after, reason, check_in_id, promotion_id, note, created_by)
  values (p_customer_id, p_delta, v_balance, p_reason, p_check_in_id, p_promotion_id, p_note, p_actor);

  perform set_config('best_nails.ledger_write', 'off', true);
  return v_balance;
end;
$$;


ALTER FUNCTION "public"."_post_points"("p_customer_id" "uuid", "p_delta" integer, "p_reason" "public"."point_reason", "p_check_in_id" "uuid", "p_promotion_id" "uuid", "p_note" "text", "p_actor" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_redeem_birthday"("p_customer_id" "uuid", "p_source" "public"."check_in_source", "p_actor" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_status jsonb;
  v_balance integer;
begin
  select points_balance into v_balance from public.customers where id = p_customer_id for update;
  v_status := public._birthday_status(p_customer_id);
  if not coalesce((v_status->>'eligible')::boolean, false) then
    return jsonb_build_object('status', case when (v_status->>'used')::boolean then 'already_used' else 'not_eligible' end);
  end if;

  if public._discount_used_today(p_customer_id) then
    return jsonb_build_object('status', 'discount_used_today');
  end if;

  insert into public.birthday_redemptions (customer_id, birthday_year, percent, source, created_by)
  values (p_customer_id, extract(year from (v_status->>'birthday')::date), (v_status->>'percent')::int, p_source, p_actor);

  return jsonb_build_object(
    'status', 'redeemed',
    'percent', (v_status->>'percent')::int,
    'points_balance', v_balance,
    'redeemed_at', now()
  );
end;
$$;


ALTER FUNCTION "public"."_redeem_birthday"("p_customer_id" "uuid", "p_source" "public"."check_in_source", "p_actor" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_shop_today"() RETURNS "date"
