    SET "search_path" TO ''
    AS $$
  select (now() at time zone timezone)::date from public.settings where id;
$$;


ALTER FUNCTION "public"."_shop_today"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."adjust_gift_voucher"("p_gift_voucher_id" "uuid", "p_delta_cents" integer, "p_note" "text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_balance integer;
begin
  if not public.is_owner() then
    raise exception 'only the owner can adjust a gift voucher' using errcode = '42501';
  end if;
  if p_delta_cents is null or p_delta_cents = 0 then
    raise exception 'enter an amount to add or remove' using errcode = '22023';
  end if;
  if p_note is null or length(trim(p_note)) = 0 then
    raise exception 'give a reason for the adjustment' using errcode = '22023';
  end if;
  select balance_cents into v_balance from public.gift_vouchers where id = p_gift_voucher_id for update;
  if not found then
    raise exception 'gift voucher not found' using errcode = 'P0002';
  end if;
  if v_balance + p_delta_cents < 0 then
    raise exception 'that would take the balance below $0' using errcode = '22023';
  end if;
  return public._post_gift_voucher(p_gift_voucher_id, 'adjust', p_delta_cents, null, p_note);
end;
$_$;


ALTER FUNCTION "public"."adjust_gift_voucher"("p_gift_voucher_id" "uuid", "p_delta_cents" integer, "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."adjust_points"("p_customer_id" "uuid", "p_delta" integer, "p_note" "text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_balance integer;
begin
  perform public.assert_staff();
  if p_delta = 0 then
    raise exception 'points must not be zero' using errcode = '22023';
  end if;
  if p_note is null or length(trim(p_note)) = 0 then
    raise exception 'a reason is required' using errcode = '22023';
  end if;

  select points_balance into v_balance from public.customers where id = p_customer_id for update;
  if not found then
    raise exception 'customer not found' using errcode = 'P0002';
  end if;
  if v_balance + p_delta < 0 then
    raise exception 'insufficient points' using errcode = '22023';
  end if;

  return public._post_points(p_customer_id, p_delta, 'adjust', null, null, trim(p_note), (select auth.uid()));
end;
$$;


ALTER FUNCTION "public"."adjust_points"("p_customer_id" "uuid", "p_delta" integer, "p_note" "text") OWNER TO "postgres";


