CREATE OR REPLACE FUNCTION "public"."check_gift_voucher"("p_code" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v public.gift_vouchers;
  v_customer public.customers;
begin
  perform public.assert_signed_in();
  select * into v from public.gift_vouchers where code = public.normalize_voucher_code(p_code);
  if not found then
    return jsonb_build_object('status', 'not_found');
  end if;
  select * into v_customer from public.customers where id = v.customer_id;

  return jsonb_build_object(
    'status', case
      when v.expires_on < public._shop_today() then 'expired'
      when v.balance_cents = 0 then 'used_up'
      else 'valid'
    end,
    'id', v.id,
    'code', v.code,
    'amount_cents', v.amount_cents,
    'balance_cents', v.balance_cents,
    'expires_on', v.expires_on,
    'customer_id', v.customer_id,
    'customer_name', nullif(trim(coalesce(v_customer.first_name, '') || ' ' || coalesce(v_customer.last_name, '')), '')
  );
end;
$$;


ALTER FUNCTION "public"."check_gift_voucher"("p_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_in_totals"("p_since" timestamp with time zone, "p_source" "public"."check_in_source" DEFAULT NULL::"public"."check_in_source") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_result jsonb;
begin
  perform public.assert_staff();
  select jsonb_build_object('visits', count(*), 'points', coalesce(sum(points_awarded), 0))
    into v_result
    from public.check_ins
   where created_at >= p_since
     and voided_at is null
     and (p_source is null or source = p_source);
  return v_result;
end;
$$;


