CREATE OR REPLACE FUNCTION "public"."guard_customer_points"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  if coalesce(current_setting('best_nails.ledger_write', true), '') <> 'on'
     and (new.points_balance is distinct from old.points_balance
          or new.lifetime_points is distinct from old.lifetime_points
          or new.visit_count is distinct from old.visit_count
          or new.last_visit_at is distinct from old.last_visit_at) then
    raise exception 'points and visits can only change through check-in, redeem or adjust'
      using errcode = '42501';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."guard_customer_points"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."guard_gift_voucher"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  if coalesce(current_setting('best_nails.ledger_write', true), '') <> 'on'
     and (new.balance_cents is distinct from old.balance_cents
          or new.amount_cents is distinct from old.amount_cents
          or new.code is distinct from old.code
          or new.sold_on is distinct from old.sold_on) then
    raise exception 'gift voucher balances only change through sell, spend, undo or adjust'
      using errcode = '42501';
  end if;
  if new.expires_on is distinct from old.expires_on and not public.is_owner() then
    raise exception 'only the owner can change a gift voucher''s expiry' using errcode = '42501';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."guard_gift_voucher"() OWNER TO "postgres";


