CREATE OR REPLACE FUNCTION "public"."redeem_reward"("p_customer_id" "uuid", "p_promotion_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_reward public.promotions;
  v_balance integer;
begin
  perform public.assert_staff();

  select * into v_reward from public.promotions
   where id = p_promotion_id and type = 'reward' and is_active;
  if not found then
    raise exception 'reward not available' using errcode = 'P0002';
  end if;

  select points_balance into v_balance from public.customers where id = p_customer_id for update;
  if not found then
    raise exception 'customer not found' using errcode = 'P0002';
  end if;
  if public._discount_used_today(p_customer_id) then
    raise exception 'they have already had a discount today (one per visit)' using errcode = '22023';
  end if;
  if v_balance < v_reward.points_cost then
    raise exception 'insufficient points' using errcode = '22023';
  end if;

  return public._post_points(p_customer_id, -v_reward.points_cost, 'redeem', null, v_reward.id, v_reward.title, (select auth.uid()));
end;
$$;


ALTER FUNCTION "public"."redeem_reward"("p_customer_id" "uuid", "p_promotion_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sell_gift_voucher"("p_amount_cents" integer, "p_code" "text" DEFAULT NULL::"text", "p_customer_id" "uuid" DEFAULT NULL::"uuid", "p_notes" "text" DEFAULT NULL::"text", "p_expires_on" "date" DEFAULT NULL::"date") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_today date := public._shop_today();
  v_code text := nullif(public.normalize_voucher_code(p_code), '');
  v_id uuid;
begin
  perform public.assert_signed_in();
  if p_amount_cents is null or p_amount_cents < 100 or p_amount_cents > 500000 then
    raise exception 'a gift voucher must be between $1 and $5,000' using errcode = '22023';
  end if;
  if p_expires_on is not null and p_expires_on < (v_today + interval '3 years')::date then
    raise exception 'gift vouchers must be valid for at least 3 years' using errcode = '22023';
  end if;
  if v_code is null then
    v_code := public._new_gift_voucher_code();
  elsif v_code !~ '^[A-Z0-9]{4,20}$' then
    raise exception 'codes must be 4 to 20 letters or numbers' using errcode = '22023';
  elsif exists (select 1 from public.gift_vouchers where code = v_code) then
    raise exception 'the code % is already used', v_code using errcode = '22023';
  end if;

  -- Starts at $0; the 'sale' ledger row puts the amount on it.
  insert into public.gift_vouchers (code, amount_cents, balance_cents, customer_id, notes, sold_on, expires_on, sold_by)
  values (v_code, p_amount_cents, 0, p_customer_id, nullif(trim(p_notes), ''), v_today,
          coalesce(p_expires_on, (v_today + interval '3 years')::date), (select auth.uid()))
  returning id into v_id;
  perform public._post_gift_voucher(v_id, 'sale', p_amount_cents, p_customer_id);

  return jsonb_build_object('id', v_id, 'code', v_code, 'balance_cents', p_amount_cents);
exception
  -- Two tills selling the same typed code at the same moment: the unique index catches the second.
  when unique_violation then
    raise exception 'the code % is already used', v_code using errcode = '22023';
end;
$_$;


ALTER FUNCTION "public"."sell_gift_voucher"("p_amount_cents" integer, "p_code" "text", "p_customer_id" "uuid", "p_notes" "text", "p_expires_on" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."shop_day_start"("p_days_ago" integer DEFAULT 0) RETURNS timestamp with time zone
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select (date_trunc('day', now() at time zone s.timezone) - make_interval(days => p_days_ago)) at time zone s.timezone
    from public.settings s
   where s.id;
$$;


ALTER FUNCTION "public"."shop_day_start"("p_days_ago" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."spend_gift_voucher"("p_code" "text", "p_amount_cents" integer, "p_customer_id" "uuid" DEFAULT NULL::"uuid", "p_note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_id uuid;
  v_result jsonb;
  v_spend integer;
  v_balance integer;
begin
  perform public.assert_signed_in();
  if p_amount_cents is null or p_amount_cents < 1 or p_amount_cents > 500000 then
    raise exception 'enter the amount for today''s service' using errcode = '22023';
  end if;
  -- Lock the voucher so two tills can't spend the same balance.
  select id into v_id from public.gift_vouchers where code = public.normalize_voucher_code(p_code) for update;
  if v_id is null then
    return jsonb_build_object('status', 'not_found');
  end if;

  v_result := public.check_gift_voucher(p_code);
  if v_result->>'status' <> 'valid' then
    return v_result;
  end if;

  -- More than is left: spend nothing and say how much there is, so staff enter that amount and
  -- take the rest at the till, rather than the voucher quietly covering only part of it.
  if p_amount_cents > (v_result->>'balance_cents')::int then
    return v_result || jsonb_build_object('status', 'over_balance');
  end if;

  v_spend := p_amount_cents;
  v_balance := public._post_gift_voucher(v_id, 'spend', -v_spend, p_customer_id, p_note);

  return v_result || jsonb_build_object(
    'status', 'spent',
    'spent_cents', v_spend,
    'balance_cents', v_balance,
    'still_to_pay_cents', 0
  );
end;
$$;


ALTER FUNCTION "public"."spend_gift_voucher"("p_code" "text", "p_amount_cents" integer, "p_customer_id" "uuid", "p_note" "text") OWNER TO "postgres";


